@keyframes ember-rise{from{background-position:0 0,0 0,97% 80%,97% 80%,0 0,0 0}to{background-position:240px -1440px,-180px -720px,97% 80%,97% 80%,0 0,0 0}}
@keyframes glint{from{background-position:150% 0}to{background-position:-50% 0}}
@keyframes hglint{from{background-position:-30% 100%,0 0}to{background-position:130% 100%,0 0}}
@keyframes sglint{from{background-position:100% -30%,0 0}to{background-position:100% 130%,0 0}}
