[data-workspace-area="conversation"] .messages-timeline-scroll,[data-workspace-area="conversation"] [data-timeline-row-kind]{background:transparent !important}
[data-user-message-bubble]{background:rgba(18,12,13,.9) !important;border:1px solid rgba(224,69,43,.22) !important}
[data-chat-header]{background:linear-gradient(90deg,transparent,rgba(255,120,50,.75),transparent) 0 100%/22% 1px no-repeat,linear-gradient(180deg,#100b0c,#09080a)!important;border-bottom:1px solid rgba(224,69,43,.14)!important;box-shadow:0 10px 24px -14px rgba(255,80,30,.22);animation:hglint 9s linear infinite}
[data-slot="sidebar-inner"]{background:linear-gradient(180deg,transparent,rgba(255,120,50,.6),transparent) 100% 0/1px 22% no-repeat,radial-gradient(ellipse 140% 30% at 50% 104%,rgba(255,90,30,.14),transparent 70%) #070607!important;border-right:1px solid rgba(224,69,43,.12);animation:sglint 11s linear infinite}
[data-thread-item]{border-radius:8px;transition:background-color .2s,box-shadow .2s}
[data-thread-item]:hover,[data-slot="button"]:hover{background-image:linear-gradient(105deg,transparent 35%,rgba(255,130,60,.2) 50%,transparent 65%)!important;background-size:250% 100%!important;animation:glint .9s ease-out}
[data-thread-item]:hover{background-color:rgba(224,69,43,.1)!important;box-shadow:inset 0 0 0 1px rgba(224,69,43,.18)}
[data-slot="button"]{transition:box-shadow .2s,color .2s}
[data-slot="button"]:hover{box-shadow:0 0 0 1px rgba(224,69,43,.3),0 0 14px -2px rgba(255,90,30,.25)!important}
[data-slot="button"]:hover svg.lucide,[data-thread-item]:hover svg.lucide{color:#ff7a3d}
[data-slot="input"]:focus,[data-slot="select-trigger"]:focus-visible{border-color:#e0452b!important;box-shadow:0 0 0 3px rgba(224,69,43,.18)!important}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-color:rgba(224,69,43,.25)!important;box-shadow:0 16px 40px -10px #000,0 0 28px -10px rgba(255,90,30,.3)!important}
[data-slot="menu-popup"] [role="menuitem"]:hover,[data-slot="menu-popup"] [data-highlighted]{background:linear-gradient(90deg,rgba(224,69,43,.24),rgba(224,69,43,.05))!important}
[data-slot="tooltip-popup"]{background:#140d0e!important;border:1px solid rgba(224,69,43,.3)!important;color:#f0d9c8!important}
[data-slot="composer-host"]{border-color:rgba(224,69,43,.3) !important;box-shadow:0 0 24px rgba(255,90,30,.07)}
[data-slot="composer-host"]:focus-within{border-color:rgba(255,90,46,.6) !important;box-shadow:0 0 28px rgba(255,90,30,.16)}
.chat-markdown-codeblock{border-left:2px solid #e0452b !important}
.chat-markdown a{color:#ff8a5c !important}
::selection{background:rgba(224,69,43,.45);color:#fff}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:linear-gradient(#e0452b,#6a1812);border-radius:8px;border:2px solid #09080a}
[data-slot="scroll-area-thumb"]{background:rgba(224,69,43,.5) !important}
